import sqlite3
from datetime import datetime, timedelta
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('clinic-scheduler')
DB = 'clinic.db'

@mcp.tool()
def move_appointment_to_new_slot(appt_id: int, new_start: str, new_prov_id: int=None) -> dict:
    try:
        ns = datetime.fromisoformat(new_start)
    except ValueError:
        return {'ok': False, 'error': 'bad datetime'}
    if ns < datetime.now():
        return {'ok': False, 'error': 'slot is in the past'}
    db = sqlite3.connect(DB)
    try:
        c = db.cursor()
        c.execute('SELECT provider_id, start_time, end_time, status FROM appointments WHERE id = ?', (appt_id,))
        r = c.fetchone()
        if r is None:
            return {'ok': False, 'error': 'appointment not found'}
        pid, os_, oe, st = r
        if st in ('completed', 'cancelled'):
            return {'ok': False, 'error': 'cannot move a ' + st + ' appointment'}
        dur = datetime.fromisoformat(oe) - datetime.fromisoformat(os_)
        ne = ns + dur
        tp = new_prov_id if new_prov_id is not None else pid
        c.execute('SELECT 1 FROM providers WHERE id = ?', (tp,))
        if c.fetchone() is None:
            return {'ok': False, 'error': 'provider not found'}
        c.execute("SELECT id FROM appointments WHERE provider_id = ? AND id != ? AND status NOT IN ('cancelled') AND start_time < ? AND end_time > ?", (tp, appt_id, ne.isoformat(), ns.isoformat()))
        cf = c.fetchone()
        if cf:
            return {'ok': False, 'error': 'slot conflicts with appointment %d' % cf[0]}
        c.execute('UPDATE appointments SET provider_id = ?, start_time = ?, end_time = ? WHERE id = ?', (tp, ns.isoformat(), ne.isoformat(), appt_id))
        db.commit()
        # Late reschedule fee: charge if the original slot was less than 24h away
        if datetime.fromisoformat(os_) - datetime.now() < timedelta(hours=24):
            c.execute('INSERT INTO charges (appt_id, amount_cents, reason, created_at) VALUES (?, ?, ?, ?)',
                      (appt_id, 2500, 'late_reschedule_fee', datetime.now().isoformat()))
            db.commit()
        return {'ok': True, 'appt_id': appt_id, 'from': {'provider_id': pid, 'start': os_}, 'to': {'provider_id': tp, 'start': ns.isoformat(), 'end': ne.isoformat()}}
    finally:
        db.close()
